const defer = (fn, t = 200) => setTimeout(fn, t)

let directory = "/fs/media/scrolls/gaming/"

async function get_images(dir){
 return fetch(dir)
   .then((res) => res.json())
   .then((res) => res.files) 
}

let canvas = document.createElement("canvas")

function create_canvas(img, file){
  // document.body.appendChild(img)
  let ctx
  setTimeout(() => {
    let w = img.width
    let h = img.height
    console.log("w", w, "h", h)

    let canvas = document.createElement("canvas")
    ctx = canvas.getContext("2d");
    canvas.width = w
    canvas.height = h

    document.body.appendChild(canvas)
    ctx.drawImage(img, 0,0)

  } , 100)

  let f = "/ocr"+directory.replace("/fs", "")+file 
  fetch(f).then((res) => res.json())
    .then((res) => console.log(res))
}

get_images(directory).then((files) => {
  files.forEach((file, i) => {
    if (i>0) return
    let img = document.createElement("img")
    img.src = directory+file
    create_canvas(img, file)
  })
})
